final class echosdk_ev_media_stats_t extends ffi.Struct {
  external echosdk_call_handle_t call;

  /// ── Packet counters ─────────────────────────────────────────────────
  @ffi.Uint32()
  external int packets_sent;

  @ffi.Uint32()
  external int packets_received;

  /// TX-side: packets remote did not receive
  /// (cumulative for the call, per RFC 3550)
  @ffi.Uint32()
  external int packets_lost;

  /// RX-side: packets we did not receive
  /// (cumulative for the call, per RFC 3550)
  @ffi.Uint32()
  external int packets_lost_rx;

  /// total RTP bytes sent
  @ffi.Uint32()
  external int bytes_sent;

  /// total RTP bytes received
  @ffi.Uint32()
  external int bytes_received;

  /// RTP transmit errors
  @ffi.Uint32()
  external int tx_errors;

  /// RTP receive errors
  @ffi.Uint32()
  external int rx_errors;

  /// TX-side loss % this window
  @ffi.Float()
  external double loss_pct;

  /// RX-side loss % this window
  @ffi.Float()
  external double loss_pct_rx;

  /// RX interarrival jitter ms (what we observe),
  /// RFC 3550 6.4.1
  @ffi.Float()
  external double jitter_ms;

  /// TX interarrival jitter ms (what remote
  /// reports in its RR)
  @ffi.Float()
  external double tx_jitter_ms;

  /// round-trip time ms
  @ffi.Float()
  external double rtt_ms;

  /// current adaptive buffer depth (ms)
  @ffi.Uint32()
  external int jitter_buffer_ms;

  /// packets currently held in buffer
  @ffi.Uint32()
  external int jitter_buffer_load;

  /// packets that arrived too late
  @ffi.Uint32()
  external int late_packets;

  /// packets discarded (overflow / flush)
  @ffi.Uint32()
  external int discarded_packets;

  /// JB current jitter estimate (ms)
  @ffi.Uint32()
  external int jitter_buffer_target_ms;

  /// true when JB is in adaptive mode
  @ffi.Bool()
  external bool jitter_buffer_adaptive;

  /// frames lost at jitter buffer (PLC trigger count)
  @ffi.Uint32()
  external int plc_frames;

  /// plc_frames / total_rx_frames (0.0–1.0)
  @ffi.Float()
  external double plc_ratio;

  /// current TX bitrate (kbps)
  @ffi.Uint32()
  external int bandwidth_kbps_tx;

  /// current RX bitrate (kbps)
  @ffi.Uint32()
  external int bandwidth_kbps_rx;

  /// session-average TX bitrate (kbps)
  @ffi.Uint32()
  external int avg_bandwidth_kbps_tx;

  /// session-average RX bitrate (kbps)
  @ffi.Uint32()
  external int avg_bandwidth_kbps_rx;

  /// TX-path listening quality  (1.0–4.5)
  @ffi.Float()
  external double mos_lq;

  /// TX-path conversational quality (1.0–4.5)
  @ffi.Float()
  external double mos_cq;

  /// RX-path listening quality (patient → you)
  @ffi.Float()
  external double mos_lq_rx;

  /// RX-path conversational quality
  @ffi.Float()
  external double mos_cq_rx;

  @ffi.Int32()
  external int mos_method;

  /// e.g. "opus", "PCMU"
  external ffi.Pointer<ffi.Char> codec_name;

  /// RTP clock rate Hz
  @ffi.Uint32()
  external int codec_clock_rate;

  /// audio sample rate Hz
  @ffi.Uint32()
  external int codec_sample_rate;

  /// 1=mono, 2=stereo
  @ffi.Uint8()
  external int codec_channels;

  /// RTP payload type number (0-127)
  @ffi.Int()
  external int payload_type;

  /// speaker (RX) level dBov (0=max, -127=silent);
  /// NaN when unavailable
  @ffi.Float()
  external double audio_level_dbov;

  /// microphone (TX) level dBov (0=max, -127=silent);
  /// NaN when unavailable
  @ffi.Float()
  external double mic_level_dbov;

  /// our SSRC
  @ffi.Uint32()
  external int ssrc_tx;

  /// remote SSRC (0 if not yet received)
  @ffi.Uint32()
  external int ssrc_rx;

  /// remote RTP address "ip:port\0"
  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> remote_addr;

  /// worst mos_lq tick this call
  @ffi.Float()
  external double mos_lq_min;

  /// session average mos_lq — averaged in the
  /// R-factor domain and converted once, since
  /// MOS is non-linear in R
  @ffi.Float()
  external double mos_lq_avg;

  /// which poll this is (1-based)
  @ffi.Uint32()
  external int stats_tick;

  /// elapsed ms since CALL_ESTABLISHED
  @ffi.Uint64()
  external int call_duration_ms;

  /// true on the last event before teardown
  @ffi.Bool()
  external bool is_final;
}

