const int ECHOSDK_VERSION_MINOR = 0;

const int ECHOSDK_VERSION_PATCH = 0;

const int ECHOSDK_AEC_OFF = 0;

const int ECHOSDK_AEC_SUPPRESSOR = 1;

const int ECHOSDK_AEC_WEBRTC = 2;

const int ECHOSDK_CONFIG_VERSION = 1;
